/bin/bash -c "python3 - <<'PY'
import cmath
verts=[(0.,0.,0.), (1.,0.,0.), (0.,1.,0.)]
xi=(1.3,2.1,0.7)
shift=(0.2,-0.1,0.3)
def dot(a,b): return sum(x*y for x,y in zip(a,b))
def sub(a,b): return tuple(x-y for x,y in zip(a,b))
def f_eq8(v):
    e=[sub(v[(p-1)%3],v[(p+1)%3]) for p in range(3)]
    return sum(cmath.exp(-1j*dot(v[p],xi))/(dot(e[(p-1)%3],xi)*dot(e[(p+1)%3],xi)) for p in range(3))
def g_eq11(s):
    return sum(-cmath.exp(1j*s[p])/((s[p]-s[(p+1)%3])*(s[p]-s[(p+2)%3])) for p in range(3))
def f_eq11(v):
    e=[sub(v[(p-1)%3],v[(p+1)%3]) for p in range(3)]
    return g_eq11([dot(a,xi) for a in e])
v_shift=[tuple(a+b for a,b in zip(v,shift)) for v in verts]
phase=cmath.exp(-1j*dot(shift,xi))
print('Equation 8, original:',f_eq8(verts))
print('Equation 11, stated edge arguments:',f_eq11(verts))
print('Equation 8 translation identity error:',abs(f_eq8(v_shift)-phase*f_eq8(verts)))
print('Equation 11 translation identity error:',abs(f_eq11(v_shift)-phase*f_eq11(verts)))
print('Equation 11 near repeated argument u=1:',g_eq11([1-0.001,1,1+0.001]))
print('Equation 12b at u=1:',cmath.exp(-1j)/2)
PY"
